-- Build 131 — PILI's sales history (Jan–Oct 2026) gets its cost, capital and agent commission per DR,
-- from the owner's DR sales record (PILI feed data, "Sales Record" sheet: 2,153 DRs, ₱6,899,046.05,
-- the same DRs and totals as the loaded history sales and the Dashboard). The Sales Manager app then
-- shows PILI's history margins. Only matched history sales (same DR, same total, no item lines) are
-- updated; nothing posts to Finance (the monthly history journals stay as they are).
-- Cost = the record's Total Cost (margin = (sales - cost) / sales, as in the record's Gross Margin).
-- A DR recorded with no cost keeps the cost unknown and stays out of the margin.

alter table public.storefront_sales add column if not exists history_cost numeric(14,2);
alter table public.storefront_sales add column if not exists history_capital numeric(14,2);
alter table public.storefront_sales add column if not exists history_commission numeric(14,2);
comment on column public.storefront_sales.history_cost is 'Loaded sales history only (no item lines): cost of the DR from the store''s own record.';
comment on column public.storefront_sales.history_capital is 'Loaded sales history only: capital (cost + add-on) of the DR.';
comment on column public.storefront_sales.history_commission is 'Loaded sales history only: agent commission of the DR (record only, not paid through the app).';

